pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { 
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}(); 
    }
    function testRegression_property() public {
        address player = address(0x42);
        vm.deal(player, 1 ether);

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(bytes32(0))));

        vm.roll(2);

        vm.prank(player);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
